import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void depthwise_conv2d_kernel(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int height,
    int width,
    int kernel_size,
    int stride,
    int padding,
    int out_height,
    int out_width
) {
    int batch_idx = blockIdx.x;
    int channel_idx = blockIdx.y;
    int out_h_idx = blockIdx.z * blockDim.x + threadIdx.x;
    int out_w_idx = threadIdx.y;

    if (out_h_idx >= out_height || out_w_idx >= out_width) return;

    half sum = __float2half(0.0f);

    for (int k_h = 0; k_h < kernel_size; ++k_h) {
        for (int k_w = 0; k_w < kernel_size; ++k_w) {
            int in_h = out_h_idx * stride - padding + k_h;
            int in_w = out_w_idx * stride - padding + k_w;

            if (in_h >= 0 && in_h < height && in_w >= 0 && in_w < width) {
                int input_idx = batch_idx * (in_channels * height * width) +
                               channel_idx * (height * width) +
                               in_h * width + in_w;

                int weight_idx = channel_idx * (kernel_size * kernel_size) +
                                k_h * kernel_size + k_w;

                sum = __hadd(sum, __hmul(input[input_idx], weight[weight_idx]));
            }
        }
    }

    int output_idx = batch_idx * (in_channels * out_height * out_width) +
                     channel_idx * (out_height * out_width) +
                     out_h_idx * out_width + out_w_idx;

    output[output_idx] = sum;
}

// Host wrapper function
extern "C" void launch_depthwise_conv2d(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int height,
    int width,
    int kernel_size,
    int stride,
    int padding,
    int out_height,
    int out_width
) {
    dim3 grid(batch_size, in_channels, (out_height + 15) / 16);
    dim3 block(16, 16);

    depthwise_conv2d_kernel<<<grid, block>>>(
        input, weight, output,
        batch_size, in_channels, height, width,
        kernel_size, stride, padding, out_height, out_width
    );

    cudaDeviceSynchronize();
}
"""

# Python model definition
class ModelNew(torch.nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.bias = bias

        # Initialize weights
        self.weight = torch.nn.Parameter(torch.randn(in_channels, kernel_size, kernel_size))
        if bias:
            self.bias = torch.nn.Parameter(torch.randn(in_channels))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Compile and load CUDA extension
        module = load_inline(
            name="depthwise_conv2d",
            cpp_sources=cuda_source,
            functions=["launch_depthwise_conv2d"],
            verbose=False
        )

        # Get input dimensions
        batch_size, _, height, width = x.shape

        # Calculate output dimensions
        out_height = (height + 2 * self.padding - self.kernel_size) // self.stride + 1
        out_width = (width + 2 * self.padding - self.kernel_size) // self.stride + 1

        # Ensure input is contiguous and on GPU
        x = x.contiguous().cuda().to(torch.float16)
        weight = self.weight.contiguous().cuda().to(torch.float16)

        # Create output tensor
        output = torch.empty(batch_size, self.in_channels, out_height, out_width, 
                           device=x.device, dtype=torch.float16)

        # Launch kernel
        module.launch_depthwise_conv2d(
            x.data_ptr(),
            weight.data_ptr(),
            output.data_ptr(),
            batch_size,
            self.in_channels,
            height,
            width,
            self.kernel_size,
            self.stride,
            self.padding,
            out_height,
            out_width
        )

        # Add bias if needed
        if self.bias is not None:
            bias = self.bias.contiguous().cuda().to(torch.float16)
            bias = bias.view(1, self.in_channels, 1, 1)
            output += bias

        return output

